func Main() -> int {
    return Divide(0)
}
func Divide(value: int) -> int {
    return 42 / value
}

func Main() -> int {
    return Loop(2)
}
func Loop(value: int) -> int {
    if value == 0 {
        return 0
    }
    return Loop(value - 1)
}
